    "dd-opt-007": {"prompt":"\\text{A poster of area }384\\text{ sq cm has margins of }6\\text{ cm top and bottom and }4\\text{ cm on each side. Maximum printed area}"},
    "dd-opt-008": {"prompt":"\\text{With demand }q=1000-20p\\ \\text{, the price }p\\text{ that maximizes revenue }p\\,q\\ "},
    "dd-opt-009": {"prompt":"\\text{An island is }3\\text{ km offshore and a town is }8\\text{ km along the shore. Rowing }3\\text{ km/h, running }5\\text{ km/h: the shortest time (hours)}"},
    "dd-opt-010": {"prompt":"\\text{A river is }1\\text{ km wide and a factory is }5\\text{ km downstream on the far bank. Cable costs }5\\text{ (×10,000) per km underwater and }3\\text{ (×10,000) per km on land. Minimum total cost (×10,000)}"},
    "dd-opt-011": {"prompt":"\\text{Small squares are cut from the corners of a square sheet of side }24\\text{ and the sides folded up into an open box. Maximum volume}"},
