    "dd-opt-013": {"prompt":"\\text{A rectangular beam is cut from a log of diameter }30\\text{; its strength is proportional to width}\\times\\text{ × height}^2\\text{. The maximum of this product}"},
    "dd-opt-014": {"prompt":"C(q)=q^3-6q^2+15q\\ \\text{ The minimum average cost}"},
