    "dd-par-002": {"prompt":"x=\\cos t,\\ y=\\sin 2t.\\quad t=\\frac{\\pi}{6}\\ \\text{ Find }\\ \\frac{dy}{dx}"},
    "dd-par-003": {"prompt":"x=e^t\\cos t,\\ y=e^t\\sin t.\\quad t=\\frac{\\pi}{2}\\ \\text{ Find }\\ \\frac{dy}{dx}"},
    "dd-par-004": {"prompt":"r=1+\\cos\\theta\\ \\text{: find }\\ \\frac{dy}{dx}\\text{ at }\\ \\theta=\\frac{\\pi}{2}\\ "},
    "dd-pw-001": {"prompt":"\\text{Derivative of }f(x)=\\sqrt{x^2}\\ \\text{ at }\\ x=-3\\ "},
    "dd-pw-002": {"prompt":"\\text{Derivative of }f(x)=\\sqrt[3]{x-1}\\ \\text{ at }\\ x=9\\ "},
    "dd-pw-003": {"prompt":"f(x)=x^2\\ (x\\ge 1),\\ f(x)=ax+b\\ (x<1)\\ \\text{ is differentiable everywhere; find }\\ a"},
