    "dx-eco-001": {"prompt":"\\text{Demand function }q(p)=500-4p^{2}\\text{ (units) at price }p=5\\text{ dollars.}\\quad\\text{What is the price elasticity }E=-\\dfrac{p\\,q'(p)}{q(p)}\\text{?}"},
    "dx-eco-002": {"prompt":"\\text{Demand }q(p)=1200e^{-0.05p}\\text{ at price }p=30\\text{ dollars.}\\quad\\text{What is the price elasticity }E=-\\dfrac{p\\,q'(p)}{q(p)}\\text{?}"},
    "dx-eco-003": {"prompt":"\\text{Total cost }C(x)=0.02x^{3}-1.8x^{2}+60x+800\\text{ dollars.}\\quad\\text{The marginal cost at output }x=20\\text{ units (dollars/unit)}"},
    "dx-eco-004": {"prompt":"\\text{Revenue }R(x)=x(90-0.5x)\\text{, cost }C(x)=20x+300\\text{ (dollars).}\\quad\\text{The output }x\\text{ that maximizes profit}"},
    "dx-eng-001": {"prompt":"\\text{Two lamps are }10\\text{ m apart with brightness }1\\text{ and }8\\text{ (intensity inversely proportional to distance squared).}\\quad\\text{How far from the first lamp is the darkest point between them?}"},
    "dx-eng-002": {"prompt":"\\text{A rectangular beam is sawn from a log of diameter }30\\text{ cm; its strength is proportional to width }\\times\\text{ × height}^{2}\\text{.}\\quad\\text{How wide (cm) is the strongest beam?}"},
    "dx-eng-003": {"prompt":"\\text{Radius of curvature of the curve }y=x^{3}-2x\\text{ at }x=1"},
