    "dx-rr-001": {"prompt":"\\text{Inverted conical tank: top radius }3\\text{ m, depth }6\\text{ m, filling at }2\\text{ cu m/min.}\\quad\\text{How fast does the level rise when the water is }4\\text{ m deep (m/min)?}"},
    "dx-rr-002": {"prompt":"\\text{A radar station is }500\\text{ m from the runway; a plane moves along the runway at }200\\text{ m/s.}\\quad\\text{When the plane is }500\\text{ m from the point opposite the radar, the rate of change of the viewing angle (rad/s)}"},
    "dx-rr-003": {"prompt":"\\text{Ship A is }60\\text{ nautical miles due north of ship B. A sails south at }15\\text{ knots and B east at }20\\text{ knots. After }\\quad 2\\text{ hours, the rate of change of the distance between them (knots)}"},
    "dx-rr-004": {"prompt":"\\text{A hot-air balloon rises vertically from a point }150\\text{ m from an observer at }6\\text{ m/s.}\\quad\\text{When it is }150\\text{ m high, the rate of change of the angle of elevation (rad/s)}"},
    "dx-tan-001": {"prompt":"\\text{Where the tangent to the curve }y=\\dfrac{x}{x^{2}+1}\\text{ at }x=2\\text{ meets the }x\\text{-axis}"},
    "dx-tan-002": {"prompt":"\\text{A tangent to }y=\\ln x\\text{ is drawn from the origin. The }x\\text{-coordinate of the point of tangency}"},
    "dx-thm-001": {"prompt":"\\text{A car travels }180\\text{ km in }2\\text{ hours, with position }s(t)=50t^{2}-10t^{3}+30t\\text{ (km).}\\quad\\text{By the mean value theorem, the time }t\\text{ (hours) when the instantaneous speed equals the average speed}"},
    "dx-thm-002": {"prompt":"\\text{Use linear approximation to estimate }\\sqrt[3]{28}\\text{ (based at }a=27\\text{)}"},
    "dx-thm-003": {"prompt":"\\text{A sphere's radius measures }10\\text{ cm with error }\\pm 0.05\\text{ cm.}\\quad\\text{Use differentials to estimate the maximum error in the volume (cu cm)}"},
    "dx-thm-004": {"prompt":"\\text{Solve }x^{3}+x-3=0\\text{ by Newton's method starting from }x_{0}=1\\text{. What is }\\quad x_{2}\\text{?}"},
    "dx-thm-005": {"prompt":"\\text{What is the behavior of }f(x)=x^{2/3}\\text{ at }x=0\\text{?}","canonical":"continuous but not differentiable","distractors":["differentiable and continuous","discontinuous","differentiable but discontinuous"]},
    "ep-001": {"prompt":"\\text{Challenge }\\lim_{x\\to 2}(3x-1)=5\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
