    "ep-004": {"prompt":"\\text{Challenge }\\lim_{x\\to 1}(x^2+x)=2\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-005": {"prompt":"\\text{Challenge }\\lim_{x\\to 2}\\frac{1}{x}=\\frac{1}{2}\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
