    "ep-007": {"prompt":"\\text{Challenge }\\lim_{x\\to 1}\\frac{x^2-1}{x-1}=2\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-008": {"prompt":"\\text{Challenge }\\lim_{x\\to 1}x^3=1\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-009": {"prompt":"\\text{Challenge }\\lim_{x\\to 0}\\frac{\\sin x}{x}=1\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-010": {"prompt":"\\text{Challenge }\\lim_{x\\to 1}(4-x^2)=3\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-011": {"prompt":"\\text{Challenge }\\lim_{x\\to 0}x\\sin\\frac{1}{x}=0\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-012": {"prompt":"\\text{Challenge }\\lim_{x\\to 1}\\frac{1}{\\sqrt{x}}=1\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-013": {"prompt":"\\text{Challenge }\\lim_{x\\to 0}e^x=1\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "ep-014": {"prompt":"\\text{Challenge }\\lim_{x\\to 0}\\ln(1+x)=0\\text{: given }\\varepsilon\\text{, find a }\\delta\\quad\\text{ (three levels)}"},
    "exam-der-012": {"prompt":"\\text{If }y=x^2e^x\\text{, find }\\frac{y'}{y}"},
