    "exam-multi-010": {"prompt":"\\text{Find the }z\\text{-component of }\\nabla\\times(y^2,\\ z^2,\\ x^2)"},
    "exam-ser-001": {"prompt":"\\text{Radius of convergence: }\\sum_{n=1}^{\\infty}\\frac{n x^n}{3^n}"},
