    "lec-18-q2a": {"prompt":"\\text{Let }\\,f(x,y)=x^2-2xy+2y\\text{ on the rectangle }\\,R=\\{0\\le x\\le3,\\ 0\\le y\\le2\\}\\text{. Find the function value at the unique critical point in the interior of }\\,R"},
    "lec-18-q2b": {"prompt":"\\text{Let }\\,f(x,y)=x^2-2xy+2y\\text{ on the rectangle }\\,R=\\{0\\le x\\le3,\\ 0\\le y\\le2\\}\\text{. Find the maximum of }\\,f\\text{ on the edge }\\,x=3"},
    "lec-18-q2c": {"prompt":"\\text{Find the absolute maximum of }\\,f(x,y)=x^2-2xy+2y\\text{ on the rectangle }\\,R=\\{0\\le x\\le3,\\ 0\\le y\\le2\\}"},
