    "lec-20-q2c": {"prompt":"\\text{Conservative field }\\mathbf{F}=(2xy,\\ x^2+2yz,\\ y^2)\\text{. Find }\\int_C\\mathbf{F}\\cdot d\\mathbf{r}\\text{, where }\\,C\\text{ is any smooth curve from }(0,0,0)\\text{ to }(1,2,3)"},
